package lk.gov.health.govcare.ai;
import org.springframework.stereotype.Component;import java.math.*;import java.util.*;import static lk.gov.health.govcare.ai.AiRiskDtos.*;
@Component public class DeteriorationRiskEngine{
 public ScoreResult score(AssessmentRequest r){req(r.respiratoryRate(),"Respiratory rate");req(r.oxygenSaturation(),"Oxygen saturation");req(r.systolicBloodPressure(),"Systolic blood pressure");req(r.pulse(),"Pulse");req(r.temperature(),"Temperature");List<Factor>f=new ArrayList<>();
  add(f,"RR","Respiratory rate",r.respiratoryRate(),range(r.respiratoryRate(),12,20,9,24,8,25),"/min","Breathing rate outside the adult reference band");
  int o=r.oxygenSaturation().compareTo(n(92))<=0?3:r.oxygenSaturation().compareTo(n(94))<=0?2:r.oxygenSaturation().compareTo(n(96))<=0?1:0;add(f,"SPO2","Oxygen saturation",r.oxygenSaturation(),o,"%","Reduced peripheral oxygen saturation");
  int b=r.systolicBloodPressure().compareTo(n(90))<=0?3:r.systolicBloodPressure().compareTo(n(100))<=0?2:r.systolicBloodPressure().compareTo(n(110))<=0?1:r.systolicBloodPressure().compareTo(n(220))>=0?3:0;add(f,"SBP","Systolic blood pressure",r.systolicBloodPressure(),b,"mmHg","Blood pressure outside the expected adult range");
  int p=r.pulse().compareTo(n(40))<=0?3:r.pulse().compareTo(n(50))<=0?1:r.pulse().compareTo(n(90))<=0?0:r.pulse().compareTo(n(110))<=0?1:r.pulse().compareTo(n(130))<=0?2:3;add(f,"PULSE","Pulse",r.pulse(),p,"bpm","Pulse outside the expected adult range");
  int t=r.temperature().compareTo(n(35))<=0?3:r.temperature().compareTo(n(36))<=0?1:r.temperature().compareTo(n(38))<=0?0:r.temperature().compareTo(n(39))<=0?1:2;add(f,"TEMP","Temperature",r.temperature(),t,"°C","Temperature outside the expected adult range");
  if(Boolean.TRUE.equals(r.supplementalOxygen()))f.add(new Factor("OXYGEN","Supplemental oxygen",2,"Yes","Current oxygen therapy increases observation priority"));if(Boolean.TRUE.equals(r.alteredMentalState()))f.add(new Factor("MENTAL","Altered mental state",3,"Yes","New confusion or reduced consciousness requires urgent review"));
  lab(f,"WBC","White blood cells",r.wbc(),4000,11000,2500,20000,"/cumm");lab(f,"HB","Haemoglobin",r.haemoglobin(),10,18,7,20,"g/dL");lab(f,"PLT","Platelets",r.platelets(),100000,450000,50000,700000,"/cumm");
  int total=Math.min(f.stream().mapToInt(Factor::points).sum(),30);String risk=total>=12?"CRITICAL":total>=7?"HIGH":total>=4?"MEDIUM":"LOW";long present=5+java.util.stream.Stream.of(r.wbc(),r.haemoglobin(),r.platelets()).filter(Objects::nonNull).count();BigDecimal confidence=BigDecimal.valueOf(55+(present/8.0)*40).setScale(1,RoundingMode.HALF_UP);String rec=switch(risk){case"CRITICAL"->"Immediate senior clinical review and continuous monitoring.";case"HIGH"->"Urgent clinician review and repeat observations within 30 minutes.";case"MEDIUM"->"Clinician review and repeat observations within 60 minutes.";default->"Continue routine observations; reassess if the clinical condition changes.";};Map<String,Object>inputs=new LinkedHashMap<>();inputs.put("respiratoryRate",r.respiratoryRate());inputs.put("oxygenSaturation",r.oxygenSaturation());inputs.put("systolicBloodPressure",r.systolicBloodPressure());inputs.put("pulse",r.pulse());inputs.put("temperature",r.temperature());inputs.put("wbc",r.wbc());inputs.put("haemoglobin",r.haemoglobin());inputs.put("platelets",r.platelets());inputs.put("supplementalOxygen",Boolean.TRUE.equals(r.supplementalOxygen()));inputs.put("alteredMentalState",Boolean.TRUE.equals(r.alteredMentalState()));return new ScoreResult(total,risk,confidence,f,rec,inputs);}
 private static void req(BigDecimal v,String x){if(v==null)throw new IllegalArgumentException(x+" is required.");}private static BigDecimal n(double x){return BigDecimal.valueOf(x);}private static int range(BigDecimal v,double nl,double nh,double dl,double dh,double cl,double ch){if(v.compareTo(n(cl))<=0||v.compareTo(n(ch))>=0)return 3;if(v.compareTo(n(dl))<=0||v.compareTo(n(dh))>=0)return 2;if(v.compareTo(n(nl))<0||v.compareTo(n(nh))>0)return 1;return 0;}private static void add(List<Factor>f,String c,String l,BigDecimal v,int p,String u,String e){if(p>0)f.add(new Factor(c,l,p,v.stripTrailingZeros().toPlainString()+" "+u,e));}private static void lab(List<Factor>f,String c,String l,BigDecimal v,double low,double high,double cl,double ch,String u){if(v==null)return;int p=v.compareTo(n(cl))<=0||v.compareTo(n(ch))>=0?2:v.compareTo(n(low))<0||v.compareTo(n(high))>0?1:0;add(f,c,l,v,p,u,"Abnormal latest CBC value");}}
